# -*- coding: utf-8 -*-
# (speaker, german, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
C, H, MA, B, DI, U, L = "Clara", "Heinrich", "Matthias", "Bernd", "Dieter", "Uwe", "Leon"
D = [
(None, "Freitag, 13. März, 16:45 Uhr. Solingen-Wald, Werkshalle 2 der Klingenwerk Hartmann GmbH. Zwischen den Schleifmaschinen stehen Stehtische, ein Bierwagen und ein Banner: „75 Jahre Heinrich Hartmann – 50 Jahre im Werk“. Clara Hartmann, 33, kommt direkt vom ICE aus München, den Rollkoffer noch in der Hand.", "3월 13일 금요일 오후 4시 45분. 졸링겐-발트, 클링겐베르크 하르트만 유한회사의 제2작업동. 연마기 사이에 스탠딩 테이블과 맥주 수레, 그리고 현수막이 서 있다. '하인리히 하르트만 75세 – 근속 50년'. 서른세 살의 클라라 하르트만이 뮌헨에서 ICE를 타고 곧장 도착한다. 손에는 아직 여행 가방이 들려 있다."),
("#", "Szene 1 – Werkshalle, kurz vor der Feier", "장면 1 – 작업동, 행사 직전"),
(L, "Guten Tag! Entschuldigung, die Feier fängt erst um fünf an. Kann ich Ihnen helfen?", "안녕하세요! 죄송하지만 행사는 5시에야 시작해요. 도와드릴까요?"),
(C, "Danke, ich finde mich schon zurecht. Ich bin hier aufgewachsen.", "고마워요, 길은 알아요. 여기서 자랐거든요."),
(L, "Oh... Dann sind Sie bestimmt Frau Hartmann. Die Tochter vom Chef.", "아... 그럼 하르트만 씨시군요. 사장님 따님."),
(C, "Clara reicht. Und du bist...?", "클라라면 돼요. 그리고 넌...?"),
(L, "Leon Neumann. Ich bin Azubi, Schneidwerkzeugmechaniker, im zweiten Lehrjahr.", "레온 노이만입니다. 절삭공구 기계공 견습생이고, 2년 차예요."),
(C, "Freut mich, Leon. Weißt du, wo mein Vater ist?", "반가워, 레온. 아버지가 어디 계신지 아니?"),
(L, "In seinem Büro. Er schreibt seine Rede zum dritten Mal neu.", "사무실에 계세요. 연설문을 세 번째로 다시 쓰고 계세요."),
(None, "Hinter einer Schleifmaschine taucht ein Mann mit grauem Schnurrbart auf, die Hände noch schwarz vom Schleifstaub.", "연마기 뒤에서 회색 콧수염의 남자가 나타난다. 손은 아직 연마 가루로 시커멓다."),
(B, "Na, sieh mal einer an. Die Clara. Aus München eingeflogen.", "이게 누구야. 클라라잖아. 뮌헨에서 날아왔구먼."),
(C, "Bernd! Mit dem Zug, nicht mit dem Flugzeug. Schön, dich zu sehen.", "베른트! 비행기 말고 기차로요. 반가워요."),
(B, "Ich hab dir das Schleifen beigebracht, als du zwölf warst. Weißt du noch?", "네가 열두 살 때 내가 연마를 가르쳤지. 기억나?"),
(C, "Natürlich. Ich hatte drei Pflaster an den Fingern.", "당연하죠. 손가락에 반창고를 세 개나 붙였었죠."),
(B, "Vier. Ich hab mitgezählt.", "네 개. 내가 셌어."),
(DI, "(kommt mit einem Tablett Gläser) Frau Hartmann, willkommen zu Hause. Ihr Vater wird sich freuen.", "(잔이 담긴 쟁반을 들고 오며) 하르트만 씨, 집에 오신 걸 환영합니다. 아버님이 기뻐하실 겁니다."),
(C, "Danke, Herr Brandt. Wie geht es ihm wirklich?", "감사합니다, 브란트 씨. 아버지는 실제로 어떠세요?"),
(DI, "Gesundheitlich gut. Aber er ist nervös. So habe ich ihn seit der Finanzkrise nicht mehr gesehen.", "건강은 좋으십니다. 하지만 긴장하셨어요. 금융위기 이후로 저런 모습은 처음 봅니다."),
(C, "Wegen der Rede?", "연설 때문에요?"),
(DI, "Eher wegen dessen, was darin steht.", "그보다는 연설에 담긴 내용 때문이겠죠."),
(B, "Was steht denn drin? Weiß das hier irgendjemand?", "대체 뭐가 쓰여 있는데? 여기 아는 사람 있어?"),
(DI, "Herr Kowalski, um siebzehn Uhr wissen es alle.", "코발스키 씨, 다섯 시면 모두 알게 됩니다."),
(B, "(leise zu Clara) Du weißt es, oder? Du bist nicht nur zum Kuchenessen gekommen.", "(클라라에게 조용히) 넌 알지? 케이크 먹으러만 온 건 아니잖아."),
(C, "Bernd, lass uns erst mal anstoßen.", "베른트, 일단 건배부터 해요."),

("#", "Szene 2 – Die Rede, 17:05 Uhr", "장면 2 – 연설, 오후 5시 5분"),
(None, "Rund zweihundert Beschäftigte stehen in der Halle. Heinrich Hartmann, 75, steigt auf eine Palette, über die man ein rotes Tuch gelegt hat, und klopft mit einem Messer an sein Glas.", "약 200명의 직원이 작업동에 서 있다. 일흔다섯의 하인리히 하르트만이 붉은 천을 덮은 팔레트 위로 올라가 칼로 잔을 두드린다."),
(H, "Liebe Kolleginnen und Kollegen, liebe Familie. Ich habe nicht vor, eine lange Rede zu halten.", "친애하는 동료 여러분, 사랑하는 가족 여러분. 길게 연설할 생각은 없습니다."),
(U, "(ruft) Das sagst du jedes Jahr, Heinrich!", "(외치며) 매년 그렇게 말하잖아요, 하인리히!"),
(H, "Und jedes Jahr glaubt ihr es mir. Das nennt man Vertrauen. (Gelächter) Vor fünfzig Jahren habe ich hier als Lehrling angefangen. Mein Vater hat mir keinen Schreibtisch gegeben, sondern einen Schleifstein.", "그리고 매년 다들 믿어 주지. 그걸 신뢰라고 하는 거야. (웃음소리) 50년 전 저는 여기서 견습생으로 시작했습니다. 아버지는 제게 책상이 아니라 숫돌을 주셨죠."),
(B, "Und einen Meister, der streng war!", "그리고 엄한 마이스터도요!"),
(H, "Genau, Bernd. Dein Vorgänger hat mich zwei Jahre lang nur Taschenmesser schleifen lassen.", "맞아, 베른트. 자네 전임자가 2년 동안 나한테 주머니칼만 갈게 했지."),
(MA, "(leise zu Clara) Jetzt kommt's.", "(클라라에게 조용히) 이제 나온다."),
(H, "Heute bin ich fünfundsiebzig. Und ein guter Handwerker weiß, wann er das Werkzeug aus der Hand legen muss.", "오늘 저는 일흔다섯입니다. 좋은 장인은 언제 연장을 내려놓아야 하는지 압니다."),
(U, "Heißt das, du hörst auf?", "그만두신다는 뜻이에요?"),
(H, "Das heißt, dass ich die Geschäftsführung zum ersten Juli abgebe. Ich bleibe Gesellschafter und ziehe mich in den Beirat zurück.", "7월 1일부로 경영권을 넘긴다는 뜻이야. 지분은 그대로 갖고 자문위원회로 물러나겠네."),
(B, "Und wer übernimmt?", "그럼 누가 맡습니까?"),
(H, "Meine Tochter Clara. Sie hat zehn Jahre in der Unternehmensberatung gearbeitet. Sie kennt Zahlen, Märkte und Menschen. Und sie hatte hier schon vier Pflaster an den Fingern.", "제 딸 클라라입니다. 10년간 경영 컨설팅에서 일했습니다. 숫자와 시장과 사람을 압니다. 그리고 이미 여기서 손가락에 반창고를 네 개나 붙였었죠."),
(None, "Applaus, aber nicht von allen. Matthias Hartmann, 40, Vertriebsleiter Inland, klatscht langsam. Bernd verschränkt die Arme.", "박수가 나오지만 모두가 치지는 않는다. 마흔 살의 국내영업 책임자 마티아스 하르트만이 느리게 손뼉을 친다. 베른트는 팔짱을 낀다."),
(MA, "(zu sich) Natürlich. Wer sonst.", "(혼잣말로) 당연하지. 누구겠어."),
(H, "Clara, möchtest du ein paar Worte sagen?", "클라라, 몇 마디 하겠니?"),
(C, "(steigt auf die Palette) Danke, Papa. Ich weiß, dass viele von Ihnen jetzt skeptisch sind. Das verstehe ich.", "(팔레트에 오르며) 고마워요, 아빠. 지금 많은 분이 회의적이시라는 걸 압니다. 이해합니다."),
(B, "(halblaut) Skeptisch ist gar kein Ausdruck.", "(반쯤 들리게) 회의적이라는 말로는 어림도 없지."),
(C, "Ich habe nicht vor, hier alles umzukrempeln. Ich will zuerst zuhören. In den nächsten hundert Tagen mache ich eine Bestandsaufnahme: jede Abteilung, jede Maschine, jedes Gespräch.", "여기서 모든 걸 뒤엎을 생각은 없습니다. 먼저 듣고 싶습니다. 앞으로 100일 동안 현황 점검을 하겠습니다. 모든 부서, 모든 기계, 모든 대화를요."),
(U, "Und danach?", "그다음엔요?"),
(C, "Danach entscheiden wir gemeinsam. Aber eins sage ich ganz ehrlich: So wie bisher können wir nicht weitermachen.", "그다음엔 함께 결정합니다. 하지만 한 가지는 아주 솔직하게 말씀드리겠습니다. 지금까지처럼은 계속할 수 없습니다."),
(None, "Stille. Dann hebt Heinrich sein Glas.", "정적. 그러다 하인리히가 잔을 든다."),
(H, "Auf Klingenwerk Hartmann. Und auf die nächsten hundert Jahre!", "클링겐베르크 하르트만을 위하여. 그리고 다음 100년을 위하여!"),

("#", "Szene 3 – Am Stehtisch neben der Härterei", "장면 3 – 열처리실 옆 스탠딩 테이블"),
(MA, "Glückwunsch, Frau Geschäftsführerin.", "축하해, 사장님."),
(C, "Matthias, bitte. Nicht so.", "마티아스, 제발. 그러지 마."),
(MA, "Wie denn sonst? Ich bin seit fünfzehn Jahren hier. Ich habe jeden Einkäufer zwischen Hamburg und München persönlich besucht. Und du kommst mit dem ICE und bekommst die Schlüssel.", "그럼 어떻게? 난 15년째 여기 있어. 함부르크에서 뮌헨까지 구매 담당자는 다 직접 찾아다녔지. 그런데 넌 ICE 타고 와서 열쇠를 받는구나."),
(C, "Ich habe Papa nicht darum gebeten. Er hat mich gefragt.", "내가 아빠한테 부탁한 거 아니야. 아빠가 나한테 물어보신 거야."),
(MA, "Und du hast natürlich sofort Ja gesagt.", "그리고 넌 당연히 바로 좋다고 했겠지."),
(C, "Nein. Ich habe ein halbes Jahr überlegt. Und ich habe gesagt, dass ich es nur mache, wenn du an Bord bleibst.", "아니. 반년 동안 고민했어. 그리고 오빠가 함께 남아야만 하겠다고 했어."),
(MA, "An Bord. Wie auf einem sinkenden Schiff?", "함께 남는다라. 가라앉는 배처럼?"),
(DI, "(tritt dazu) Ich störe ungern, aber das Wort „sinkend“ möchte ich nicht unkommentiert lassen.", "(다가오며) 방해하고 싶진 않지만 '가라앉는'이라는 말은 그냥 넘길 수 없군요."),
(C, "Herr Brandt, wie schlimm ist es? Ganz ehrlich.", "브란트 씨, 얼마나 심각한가요? 아주 솔직하게요."),
(DI, "Wir sinken nicht. Aber wir verlieren an Höhe. Umsatz achtundvierzig Millionen, minus drei Prozent. Die Marge schrumpft seit drei Jahren.", "가라앉고 있지는 않습니다. 하지만 고도를 잃고 있어요. 매출 4,800만 유로, 3% 감소. 마진은 3년째 줄고 있습니다."),
(MA, "Weil uns die Handelsketten die Preise diktieren und das Internet voller Billigmesser aus Fernost ist.", "유통 체인들이 가격을 강요하고 인터넷엔 극동산 싸구려 칼이 넘쳐나니까."),
(C, "Und weil wir zu achtundachtzig Prozent vom deutschen Markt abhängen.", "그리고 우리가 독일 시장에 88%나 의존하니까."),
(MA, "Ach, daher weht der Wind. Export. Das stand in jeder Beraterpräsentation, die ich je gesehen habe.", "아, 바람이 그쪽에서 부는군. 수출. 내가 본 컨설턴트 발표마다 다 나오던 얘기지."),
(C, "Dann hast du sicher auch gelesen, dass „Solingen“ im Ausland ein Qualitätsversprechen ist. In Seoul oder Tokio zahlt man für ein Hartmann-Messer das Doppelte.", "그럼 '졸링겐'이 해외에선 품질의 약속이라는 것도 읽었겠네. 서울이나 도쿄에선 하르트만 칼에 두 배를 내."),
(DI, "Theoretisch. Praktisch liegt unsere Exportquote bei zwölf Prozent, und das fast nur in Österreich, der Schweiz und den Niederlanden.", "이론적으로는요. 실제 수출 비중은 12%이고, 그것도 거의 오스트리아, 스위스, 네덜란드뿐입니다."),
(C, "Eben. Da liegt Potenzial brach.", "그러니까요. 잠재력이 놀고 있는 거예요."),
(MA, "Und wer soll das machen? Ich habe zwei Außendienstler und eine Assistentin.", "그걸 누가 해? 난 외근 영업사원 둘에 비서 하나야."),
(C, "Ich. Am Anfang mache ich es selbst. Das wird mein Projekt.", "내가. 처음엔 내가 직접 할 거야. 그게 내 프로젝트가 될 거야."),
(DI, "Darf ich Ihnen einen Rat geben, Frau Hartmann?", "조언 하나 드려도 되겠습니까, 하르트만 씨?"),
(C, "Bitte.", "그러세요."),
(DI, "Machen Sie daraus ein richtiges Projekt. Mit Machbarkeitsstudie, Budget und Meilensteinen. Sonst redet es Ihnen jeder in der ersten Sitzung kaputt.", "제대로 된 프로젝트로 만드세요. 타당성 조사, 예산, 마일스톤까지 갖춰서요. 안 그러면 첫 회의에서 다들 말로 무너뜨릴 겁니다."),
(MA, "Zum Beispiel ich.", "예를 들면 나."),
(C, "(lächelt) Zum Beispiel du. Deshalb will ich dich im Projektteam haben.", "(미소 지으며) 예를 들면 오빠. 그래서 오빠를 프로젝트 팀에 넣고 싶은 거야."),
(MA, "Ich überlege es mir. Aber erwarte keine Begeisterung.", "생각해 볼게. 하지만 열광은 기대하지 마."),

("#", "Szene 4 – Hinter der Schleiferei, 18:20 Uhr", "장면 4 – 연마실 뒤편, 오후 6시 20분"),
(None, "An der Laderampe stehen Uwe Krämer, der Betriebsratsvorsitzende, und Bernd mit ihren Bierflaschen. Leon räumt leere Kisten weg.", "하역장에 노사협의회 의장 우베 크레머와 베른트가 맥주병을 들고 서 있다. 레온은 빈 상자를 치우고 있다."),
(U, "Hundert Tage Bestandsaufnahme. Weißt du, was das in Beratersprache heißt, Bernd?", "100일 현황 점검. 그게 컨설턴트 말로 무슨 뜻인지 알아, 베른트?"),
(B, "Dass danach Leute gehen müssen.", "그 뒤에 사람들이 나가야 한다는 거지."),
(U, "Genau. Ich kenne die Sprüche. Erst heißt es „Prozesse optimieren“, dann „Strukturen verschlanken“.", "바로 그거야. 그런 말들 다 알지. 처음엔 '프로세스 최적화', 그다음엔 '조직 슬림화'."),
(L, "Aber vielleicht will sie ja wachsen und nicht sparen?", "그런데 어쩌면 아끼려는 게 아니라 성장하려는 걸 수도 있잖아요?"),
(B, "Du bist neunzehn, Leon. Du glaubst auch noch an den Weihnachtsmann.", "넌 열아홉이야, 레온. 아직 산타클로스도 믿는 나이지."),
(L, "Ich glaube an Zahlen. Unser Kochmesser-Video auf Instagram hat zweihunderttausend Aufrufe. Die Hälfte der Kommentare ist auf Koreanisch und Japanisch.", "저는 숫자를 믿어요. 인스타그램에 올린 식칼 영상 조회 수가 20만이에요. 댓글 절반이 한국어랑 일본어고요."),
(U, "Kommentare kaufen keine Messer.", "댓글이 칼을 사 주진 않아."),
(C, "(kommt um die Ecke) Manchmal doch.", "(모퉁이를 돌아오며) 가끔은 사 주죠."),
(None, "Uwe richtet sich auf. Bernd stellt seine Flasche ab.", "우베가 자세를 바로 한다. 베른트가 병을 내려놓는다."),
(U, "Frau Hartmann. Wir haben gerade...", "하르트만 씨. 저희가 방금..."),
(C, "...über mich geredet. Das ist in Ordnung, Herr Krämer. An Ihrer Stelle würde ich es auch tun.", "...제 얘기를 하고 계셨죠. 괜찮아요, 크레머 씨. 제가 그 입장이라도 그랬을 거예요."),
(U, "Dann frage ich direkt, als Betriebsratsvorsitzender: Sind Arbeitsplätze in Gefahr?", "그럼 노사협의회 의장으로서 직접 묻겠습니다. 일자리가 위험합니까?"),
(C, "Nicht durch mich. Durch Stillstand, ja. Wenn wir nichts ändern, sind in fünf Jahren Stellen in Gefahr.", "저 때문에는 아닙니다. 정체 때문이라면, 네. 아무것도 바꾸지 않으면 5년 뒤엔 일자리가 위험합니다."),
(U, "Das ist eine Antwort, die man auf zwei Arten verstehen kann.", "두 가지로 이해할 수 있는 답이군요."),
(C, "Dann sage ich es eindeutig: Ich will mehr verkaufen, nicht weniger Leute beschäftigen. Und alles, was die Belegschaft betrifft, bespreche ich zuerst mit dem Betriebsrat.", "그럼 분명하게 말씀드리죠. 저는 인원을 줄이는 게 아니라 더 많이 팔고 싶습니다. 그리고 직원과 관련된 일은 모두 노사협의회와 먼저 논의하겠습니다."),
(U, "Das nehme ich zu Protokoll.", "그 말씀, 기록해 두겠습니다."),
(B, "Und wo willst du mehr verkaufen? In Korea, wie der Junge mit seinem Instagram?", "그래서 어디서 더 팔 건데? 저 녀석 인스타그램처럼 한국에서?"),
(C, "Zum Beispiel. Auf der Ambiente stand letztes Jahr eine Einkäuferin aus Seoul eine halbe Stunde an unserem Stand. Sie hat nie eine Antwort bekommen.", "예를 들면요. 작년 암비엔테 박람회 때 서울에서 온 바이어가 우리 부스에 30분이나 서 있었어요. 그런데 끝내 답장을 못 받았죠."),
(B, "Und wer schleift die zusätzlichen Messer? Ich habe drei Leute, die in den nächsten fünf Jahren in Rente gehen. Und Nachwuchs? Einen. (zeigt auf Leon)", "그럼 늘어난 칼은 누가 갈아? 앞으로 5년 안에 은퇴할 사람이 셋이야. 그리고 후계자는? 하나. (레온을 가리킨다)"),
(L, "Ich hätte noch zwei Freunde von der Berufsschule, die Interesse hätten.", "직업학교 친구 둘도 관심 있을 거예요."),
(C, "Siehst du, Bernd? Bestandsaufnahme, Tag eins. Erstes Problem: Fachkräftemangel. Erster Lösungsansatz: Leon.", "봤죠, 베른트? 현황 점검 첫날. 첫 번째 문제: 숙련공 부족. 첫 번째 해결 실마리: 레온."),
(B, "(brummt) Du hast immer noch das große Mundwerk von früher.", "(투덜대며) 여전히 예전처럼 입이 살았구나."),
(C, "Und du immer noch das gute Herz.", "그리고 베른트는 여전히 마음이 따뜻하고요."),
(B, "Eine Frage noch. Jetzt, wo du Chefin wirst: Muss ich dich ab Juli siezen?", "하나만 더. 이제 사장이 되니까 묻는 건데, 7월부터는 너한테 존댓말 써야 하냐?"),
(C, "Wenn du mich siezt, sieze ich dich auch. Und dann wird's hier hinten sehr steif.", "베른트가 존댓말 쓰면 저도 존댓말 쓸 거예요. 그럼 여기 뒤편이 아주 딱딱해지겠죠."),
(B, "(fast lächelnd) Dann bleibt's beim Du. Aber nur hier hinten.", "(거의 웃으며) 그럼 그냥 반말로 하자. 하지만 여기 뒤에서만이다."),

("#", "Szene 5 – Im Büro des Seniorchefs, 21:30 Uhr", "장면 5 – 회장실, 오후 9시 30분"),
(None, "Die Halle ist leer. Im Büro riecht es nach Öl und altem Papier. An der Wand hängt ein gerahmtes Foto von 1921: der Urgroßvater vor einem Schleifkotten an der Wupper.", "작업동은 비었다. 사무실에서는 기름과 오래된 종이 냄새가 난다. 벽에는 1921년의 액자 사진이 걸려 있다. 부퍼강 변의 수력 연마 공방 앞에 선 증조할아버지."),
(H, "Na? Wie war dein erster Abend als Chefin?", "그래? 사장으로서 첫 저녁은 어땠니?"),
(C, "Ich bin noch nicht Chefin, Papa. Erst ab Juli.", "아직 사장 아니에요, 아빠. 7월부터예요."),
(H, "Die Leute haben dich heute schon so angeschaut. Das zählt mehr als ein Datum im Handelsregister.", "오늘 사람들은 벌써 너를 그렇게 보더구나. 그게 상업등기부에 적힌 날짜보다 중요하단다."),
(C, "Matthias hat mich angeschaut, als hätte ich ihm etwas gestohlen.", "마티아스는 제가 뭘 훔치기라도 한 것처럼 봤어요."),
(H, "Ich weiß. Das ist meine Schuld. Ich hätte früher mit ihm reden sollen.", "안다. 내 탓이야. 더 일찍 그 애와 얘기했어야 했어."),
(C, "Warum hast du nicht ihn gefragt? Er kennt das Geschäft besser als ich.", "왜 오빠한테 묻지 않으셨어요? 오빠가 저보다 사업을 더 잘 알잖아요."),
(H, "Er kennt das Geschäft von gestern, und das macht er hervorragend. Aber das Geschäft von morgen sieht anders aus. Das hat er mir übrigens selbst einmal gesagt.", "그 애는 어제의 사업을 알고, 그걸 아주 훌륭하게 해내지. 하지만 내일의 사업은 모습이 달라. 그건 그 애가 직접 내게 한 말이기도 하다."),
(C, "Wann?", "언제요?"),
(H, "Nach der Messe in Frankfurt. Er kam zurück und sagte: „Papa, die Asiaten wollen unsere Messer, und wir wissen nicht einmal, wie man eine Proformarechnung auf Englisch schreibt.“", "프랑크푸르트 박람회가 끝나고. 돌아와서 이러더구나. '아빠, 아시아 사람들이 우리 칼을 원하는데 우린 영어로 견적 송장 쓰는 법도 몰라요.'"),
(C, "Und dann?", "그래서요?"),
(H, "Dann kam das Weihnachtsgeschäft, und niemand hatte Zeit. Wie jedes Jahr.", "그러고는 연말 대목이 왔고 아무도 시간이 없었지. 매년 그렇듯."),
(C, "Genau das meine ich mit „so wie bisher“.", "제가 말한 '지금까지처럼'이 바로 그거예요."),
(H, "Ich habe es verstanden. Ich habe nur eine Bitte. Eigentlich zwei.", "알아들었다. 부탁이 하나 있구나. 사실은 둘이다."),
(C, "Ich höre.", "듣고 있어요."),
(H, "Erstens: Der Stempel „Solingen“ bleibt auf jeder Klinge. Wir lassen nirgendwo anders fertigen. Niemals.", "첫째, '졸링겐' 각인은 모든 칼날에 남는다. 다른 곳에서 생산하게 하지 않는다. 절대로."),
(C, "Das war nie mein Plan. Der Stempel ist unser stärkstes Verkaufsargument.", "그건 처음부터 제 계획이 아니었어요. 그 각인이 우리의 가장 강력한 판매 포인트인걸요."),
(H, "Zweitens: Nimm Bernd mit. Nicht als Hindernis, sondern als Zeugen. Wenn Bernd sagt, dass ein Messer gut ist, glaubt es die ganze Belegschaft.", "둘째, 베른트를 데려가라. 걸림돌이 아니라 증인으로. 베른트가 칼이 좋다고 하면 전 직원이 믿는다."),
(C, "Und wenn er Nein sagt?", "그런데 베른트가 안 된다고 하면요?"),
(H, "Dann hör genau hin. Meistens hat er einen Grund.", "그럼 잘 들어 봐라. 대개는 이유가 있으니까."),
(None, "Heinrich öffnet eine Schublade und legt ein abgegriffenes Taschenmesser mit Hirschhorngriff auf den Tisch.", "하인리히가 서랍을 열어 손때 묻은 사슴뿔 손잡이 주머니칼을 책상 위에 올려놓는다."),
(C, "Das Messer vom Urgroßvater...", "증조할아버지의 칼..."),
(H, "Seit 1921 gibt es jeder Chef an den nächsten weiter. Mein Vater hat es mir mit einem einzigen Satz gegeben: „Eine gute Klinge verkauft sich überall – man muss sie nur zeigen.“", "1921년부터 사장마다 다음 사장에게 물려준 칼이다. 아버지는 단 한 문장과 함께 이걸 내게 주셨지. '좋은 칼날은 어디서나 팔린다. 보여 주기만 하면 된다.'"),
(C, "Überall. Er hat wirklich „überall“ gesagt?", "어디서나. 정말 '어디서나'라고 하셨어요?"),
(H, "(lächelt) Ich habe fünfzig Jahre gebraucht, um zu verstehen, dass er nicht nur Solingen gemeint hat.", "(미소 지으며) 아버지가 졸링겐만 말씀하신 게 아니라는 걸 깨닫는 데 50년이 걸렸구나."),
(None, "Es klopft. Matthias steht in der Tür, das Jackett über dem Arm.", "노크 소리. 마티아스가 재킷을 팔에 걸친 채 문간에 서 있다."),
(MA, "Störe ich?", "방해했나요?"),
(H, "Nie. Komm rein.", "절대. 들어오너라."),
(MA, "Ich wollte nur sagen... Die Einkäuferin aus Seoul. Frau Choi. Ich habe ihre Visitenkarte noch.", "그냥 말해 두려고... 서울에서 온 바이어. 최 씨. 명함 아직 갖고 있어."),
(C, "Du hast sie aufgehoben?", "그걸 버리지 않았어?"),
(MA, "Ich werfe nie etwas weg. Das habe ich von Papa. (legt die Karte auf den Tisch) Montag, neun Uhr, Jour fixe? Dann reden wir über deine Bestandsaufnahme.", "난 아무것도 안 버려. 아빠한테 배웠지. (명함을 책상에 놓으며) 월요일 9시, 정기회의 어때? 그때 네 현황 점검 얘기하자."),
(C, "Montag, neun Uhr. Ich bringe die Tagesordnung mit.", "월요일 9시. 안건은 내가 준비해 갈게."),
(MA, "Und ich die Einwände.", "그리고 난 반론을."),
(H, "(hebt sein Glas zum dritten Mal an diesem Abend) Na also. Jetzt ist es ein Familienunternehmen.", "(오늘 밤 세 번째로 잔을 들며) 그렇지. 이제야 가족기업이구나."),
]

